    int j = 0;
    int count = 0;

    for (int i = 0; i < STRING_SIZE; i++) {
        while (j > 0 && input[i] != pattern[j]) {
            j = kmpNext[j-1];
        }
        if (input[i] == pattern[j]) {
            j++;
        }
        if (j == PATTERN_SIZE) {
            count++;
            j = kmpNext[j-1];
        }
    }

    n_matches[0] = count;
    return count;
}
